import pandas as pd
import numpy as np

def clean(df):
    df['species'] = df['species'].str.strip()
    df['island'] = df['island'].str.strip()
    df['bill_length_mm'] = df['bill_length_mm'].where((df['bill_length_mm'] >= 30) & (df['bill_length_mm'] <= 60)).fillna(np.nan)
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce').where((df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)).fillna(np.nan)
    df['sex'] = df['sex'].str.strip()
    return df

def answer(df):
    adelie = df[df['species'] == 'Adelie']
    valid = adelie[adelie['bill_length_mm'].notna()]
    if valid.empty:
        return {}
    groups = valid.groupby('island')['bill_length_mm'].mean().reset_index()
    return {row['island']: row['bill_length_mm'] for row in groups}
